



import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import Login from './components/Login';
import Cadastro from './Cadastro';
import Dashboard from './components/Dashboard'; // Certifique-se de que o componente Dashboard está importado

const App = () => {
  return (
    <Router basename="/emocoes">
      <Switch>
        <Route path="/cadastro" component={Cadastro} />
        <Route path="/dashboard" component={Dashboard} /> // Adicione a rota para o Dashboard
        <Route path="/" component={Login} />
      </Switch>
    </Router>
  );
};

export default App;



