



import React, { useState } from 'react';
import { useHistory } from 'react-router-dom';
import { supabase } from '../supabaseClient'; // Certifique-se de que a importação está correta
import '../index.css';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const history = useHistory();

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) {
        throw error;
      }
      setMessage('Login realizado com sucesso!');
      setTimeout(() => {
        history.push('/dashboard'); // Certifique-se de que a rota redirecionada existe e está correta
      }, 3000);
    } catch (error) {
      setMessage('Erro ao realizar login: ' + error.message);
    }
  };

  return (
    <div className="login-container">
      <div className="login-box">
        <h2>Login</h2>
        <form onSubmit={handleLogin}>
          <div>
            <label>Email</label>
            <input 
              type="email" 
              value={email} 
              onChange={(e) => setEmail(e.target.value)} 
              required 
            />
          </div>
          <div>
            <label>Senha</label>
            <input 
              type="password" 
              value={password} 
              onChange={(e) => setPassword(e.target.value)} 
              required 
            />
          </div>
          <button type="submit">Entrar</button>
        </form>
        {message && <p>{message}</p>}
      </div>
    </div>
  );
};

export default Login;


